<script setup>
import { computed } from "vue";
import AttendanceRiskBadge from "./AttendanceRiskBadge.vue";

const props = defineProps({ data: { type: Object, required: true } });
const emit = defineEmits(["open-student", "open-cases", "filter-risk"]);
const pct = (value) => value === null || value === undefined ? "Sin datos" : `${Number(value).toLocaleString("es-CL", { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%`;
const number = (value) => Number(value || 0).toLocaleString("es-CL");
const patternLabels = {
  monday_absence: "Ausencias recurrentes los lunes", friday_absence: "Ausencias recurrentes los viernes",
  consecutive_absence: "Ausencias consecutivas", recent_attendance_drop: "Descenso reciente de asistencia",
  attendance_recovery: "Recuperación reciente de asistencia", intermittent_absence: "Ausencias intermitentes",
  pre_holiday_absence: "Ausencias antes de interrupciones", post_holiday_absence: "Ausencias después de interrupciones",
  increasing_lateness: "Aumento de atrasos", recurring_early_departure: "Retiros anticipados recurrentes",
  unjustified_absence: "Ausencias sin justificación",
};
const patternLabel = (value) => patternLabels[value] || String(value || "").replaceAll("_", " ");
const kpis = computed(() => [
  { key: "school", label: "Asistencia del colegio", value: pct(props.data.kpis?.school_attendance), icon: "bx-buildings", tone: "navy" },
  { key: "present", label: "Presentes hoy", value: number(props.data.kpis?.present_today), icon: "bx-user-check", tone: "green" },
  { key: "absent", label: "Ausentes hoy", value: number(props.data.kpis?.absent_today), icon: "bx-user-x", tone: "red" },
  { key: "unjustified", label: "Sin justificar hoy", value: number(props.data.kpis?.unjustified_today), icon: "bx-file-blank", tone: "orange" },
  { key: "critical", label: "Atención crítica", value: number(props.data.kpis?.critical_students), icon: "bx-error", tone: "critical" },
  { key: "new", label: "Casos nuevos esta semana", value: number(props.data.kpis?.new_cases_this_week), icon: "bx-folder-plus", tone: "blue" },
  { key: "recovered", label: "Casos recuperados", value: number(props.data.kpis?.recovered_cases), icon: "bx-trending-up", tone: "green" },
  { key: "lost", label: "Días de clase perdidos", value: number(props.data.kpis?.lost_school_days), icon: "bx-calendar-x", tone: "purple" },
]);
const riskSeries = computed(() => (props.data.risk_distribution || []).map((item) => item.value));
const riskOptions = computed(() => ({ chart: { type: "donut", animations: { enabled: false }, toolbar: { show: false } }, labels: (props.data.risk_distribution || []).map((item) => item.label), colors: ["#2d9b78", "#e4b52f", "#e48735", "#cf4b59", "#5e2130", "#9aa4b2"], legend: { position: "bottom", fontSize: "11px" }, dataLabels: { enabled: false }, stroke: { colors: ["#fff"], width: 3 }, plotOptions: { pie: { donut: { size: "68%", labels: { show: true, total: { show: true, label: "Estudiantes", formatter: () => riskSeries.value.reduce((sum, item) => sum + Number(item || 0), 0) } } } } }, noData: { text: "Ejecuta el análisis para visualizar datos" } }));
const courseSeries = computed(() => [{ name: "Asistencia", data: (props.data.courses || []).slice(0, 12).map((item) => item.attendance_rate) }]);
const courseOptions = computed(() => ({ chart: { type: "bar", animations: { enabled: false }, toolbar: { show: false } }, colors: ["#405189"], plotOptions: { bar: { horizontal: true, borderRadius: 4, barHeight: "58%", colors: { ranges: [{ from: 0, to: 84.99, color: "#cf4b59" }, { from: 85, to: 89.99, color: "#e48735" }, { from: 90, to: 94.99, color: "#e4b52f" }, { from: 95, to: 100, color: "#2d9b78" }] } } }, dataLabels: { enabled: true, formatter: (value) => pct(value), style: { fontSize: "10px" } }, xaxis: { categories: (props.data.courses || []).slice(0, 12).map((item) => item.name), min: 0, max: 100, labels: { formatter: (value) => `${Math.round(value)}%` } }, grid: { borderColor: "#edf0f4" }, legend: { show: false } }));
const pending = computed(() => props.data.pending_management || {});
</script>

<template>
  <section class="management-dashboard">
    <div class="kpi-grid">
      <article v-for="item in kpis" :key="item.key" class="kpi-card" :class="`tone-${item.tone}`">
        <span class="kpi-icon"><i class="bx" :class="item.icon"></i></span>
        <div><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div>
      </article>
    </div>

    <div v-if="data.meta?.analysis_status === 'pending_analysis'" class="analysis-empty">
      <i class="bx bx-data"></i><div><strong>Análisis preventivo pendiente</strong><p>La asistencia oficial está disponible, pero aún no se han generado las instantáneas de riesgo. Ejecuta <code>php artisan attendance:analyze</code> o espera el proceso diario de las 06:45.</p></div>
    </div>

    <div class="dashboard-grid">
      <article class="panel risk-panel"><header><div><span class="eyebrow">DETECCIÓN TEMPRANA</span><h2>Distribución por nivel de atención</h2></div><button type="button" class="link-button" @click="emit('open-cases')">Ver expedientes <i class="bx bx-right-arrow-alt"></i></button></header><apexchart type="donut" height="315" :options="riskOptions" :series="riskSeries" /></article>
      <article class="panel priority-panel"><header><div><span class="eyebrow">PRIORIDAD EXPLICABLE</span><h2>Estudiantes que requieren gestión</h2></div></header><div v-if="!(data.priority_students || []).length" class="empty"><i class="bx bx-check-shield"></i><span>Sin estudiantes priorizados con los filtros actuales.</span></div><button v-for="student in (data.priority_students || []).slice(0,8)" :key="student.student_id" type="button" class="priority-row" @click="emit('open-student', student.student_id)"><div class="student-rank"><strong>{{ student.name }}</strong><span>{{ pct(student.attendance_rate) }} · {{ student.lost_days }} días perdidos</span></div><div class="priority-reason"><span>{{ student.why_prioritized?.[0] || 'Revisión preventiva sugerida' }}</span><AttendanceRiskBadge :level="student.risk_level" compact /></div><i class="bx bx-chevron-right"></i></button></article>
    </div>

    <div class="dashboard-grid equal">
      <article class="panel"><header><div><span class="eyebrow">COMPARACIÓN</span><h2>Cursos con menor asistencia</h2></div></header><apexchart type="bar" height="390" :options="courseOptions" :series="courseSeries" /></article>
      <article class="panel management-panel"><header><div><span class="eyebrow">GESTIÓN PENDIENTE</span><h2>Acciones que no pueden esperar</h2></div></header><div class="pending-list"><button type="button" @click="emit('open-cases', 'detected')"><span class="pending-icon red"><i class="bx bx-search-alt"></i></span><div><strong>{{ number(pending.unreviewed_cases) }}</strong><span>casos sin revisar</span></div><i class="bx bx-chevron-right"></i></button><button type="button" @click="emit('open-cases')"><span class="pending-icon orange"><i class="bx bx-user-x"></i></span><div><strong>{{ number(pending.cases_without_responsible) }}</strong><span>sin responsable asignado</span></div><i class="bx bx-chevron-right"></i></button><button type="button" @click="emit('open-cases')"><span class="pending-icon blue"><i class="bx bx-message-square-x"></i></span><div><strong>{{ number(pending.cases_without_intervention) }}</strong><span>sin primera intervención</span></div><i class="bx bx-chevron-right"></i></button><button type="button" @click="emit('open-cases')"><span class="pending-icon purple"><i class="bx bx-calendar-exclamation"></i></span><div><strong>{{ number(pending.overdue_reviews) }}</strong><span>revisiones vencidas</span></div><i class="bx bx-chevron-right"></i></button></div><div class="effectiveness"><span>Planes evaluados</span><strong>{{ number(data.intervention_effectiveness?.evaluated_plans) }}</strong><small>{{ data.intervention_effectiveness?.improved_percentage === null ? 'Aún sin base suficiente' : `${pct(data.intervention_effectiveness.improved_percentage)} con mejora observada` }}</small><p><i class="bx bx-info-circle"></i>{{ data.intervention_effectiveness?.warning }}</p></div></article>
    </div>

    <article class="panel patterns"><header><div><span class="eyebrow">PATRONES INSTITUCIONALES</span><h2>Señales recurrentes detectadas</h2></div></header><div class="pattern-grid"><button v-for="pattern in data.patterns || []" :key="pattern.pattern_type" type="button" @click="emit('filter-risk', pattern.pattern_type)"><span class="pattern-mark"><i class="bx bx-pulse"></i></span><div><strong>{{ patternLabel(pattern.pattern_type) }}</strong><span>{{ number(pattern.total) }} estudiantes · confianza {{ pct(pattern.confidence) }}</span></div><i class="bx bx-right-arrow-alt"></i></button><div v-if="!(data.patterns || []).length" class="empty"><i class="bx bx-radar"></i><span>Sin patrones activos para el alcance seleccionado.</span></div></div></article>
  </section>
</template>

